import type { Workflow } from '../lib/types'

// Same files the README embeds; generated by scripts/build.mjs with all YAML
// text XML-escaped, so inlining them is safe.
const diagrams = import.meta.glob<string>('/docs/diagrams/*.svg', {
  query: '?raw',
  import: 'default',
  eager: true,
})

export function WorkflowDiagram({ workflow }: { workflow: Workflow }) {
  const svg = diagrams[`/docs/diagrams/${workflow.id}.svg`]
  if (!svg) return null
  return (
    <figure className="diagram">
      <figcaption className="eyebrow">Workflow diagram · {workflow.title}</figcaption>
      <div className="diagram-scroll" dangerouslySetInnerHTML={{ __html: svg }} />
    </figure>
  )
}
